<?php require '../includes/bootstrap.php';$user=admin_required();$title='Nhật ký thao tác';$count=(int)query('SELECT COUNT(*) FROM audit_logs')->fetchColumn();$pages=max(1,(int)ceil($count/50));$page=max(1,min($pages,(int)input('page','1')));$offset=($page-1)*50;$rows=query('SELECT l.*,a.display_name FROM audit_logs l LEFT JOIN admins a ON a.id=l.staff_id ORDER BY l.id DESC LIMIT 50 OFFSET '.$offset)->fetchAll();require '../includes/staff_header.php'; ?><p>Ghi nhận thao tác của nhân viên, không lưu mật khẩu. Trang <?=$page?>/<?=$pages?>.</p><div class="table-wrap"><table><thead><tr><th>Thời gian</th><th>Nhân viên</th><th>Hành động</th><th>Nội dung</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['display_name']??'Khách / hệ thống')?></td><td><?=e($r['action'])?></td><td><?=e($r['detail'])?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="4">Chưa có nhật ký.</td></tr><?php endif; ?></tbody></table></div><div class="actions"><?php if($page>1): ?><a class="button outline" href="?page=<?=$page-1?>">← TRƯỚC</a><?php endif; if($page<$pages): ?><a class="button outline" href="?page=<?=$page+1?>">TIẾP →</a><?php endif; ?></div><?php require '../includes/staff_footer.php'; ?>
